/* Rasterize the social card SVG to the PNG that OpenGraph actually points at.
 *
 * Run locally, commit the result:
 *
 *   pnpm exec playwright install chromium
 *   node scripts/render-social-card.mjs
 *
 * CI installs WebKit only (see .github/workflows/ci.yml), so this deliberately
 * is NOT wired into the build — the PNG is a committed artifact, regenerated by
 * hand when the card changes. The alternative was adding a rasterizer to the
 * dependency tree for one 1200x630 image, which is not a trade worth making.
 *
 * The SVG names Archivo / Instrument Serif / IBM Plex Mono. Those are not system
 * fonts, so the page below @font-face's them straight out of node_modules; without
 * that step Chromium silently falls back and the card ships in the wrong type. */

import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const assets = path.join(root, "apps/web/public/assets");
const modules = path.join(root, "apps/web/node_modules");

const faces = [
  ["Archivo", "@fontsource-variable/archivo/files/archivo-latin-wght-normal.woff2", 400],
  ["Instrument Serif", "@fontsource/instrument-serif/files/instrument-serif-latin-400-normal.woff2", 400],
  ["IBM Plex Mono", "@fontsource/ibm-plex-mono/files/ibm-plex-mono-latin-400-normal.woff2", 400],
];

async function fontCss() {
  const parts = [];
  for (const [family, file, weight] of faces) {
    const data = await readFile(path.join(modules, file));
    parts.push(
      `@font-face{font-family:'${family}';font-weight:${weight};` +
        `src:url(data:font/woff2;base64,${data.toString("base64")}) format('woff2');}`,
    );
  }
  return parts.join("\n");
}

const svg = await readFile(path.join(assets, "social-card.svg"), "utf8");
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1200, height: 630 }, deviceScaleFactor: 1 });
await page.setContent(
  `<style>${await fontCss()}html,body{margin:0;background:#0A0908}svg{display:block}</style>${svg}`,
  { waitUntil: "load" },
);
await page.evaluate(() => document.fonts.ready);
const png = await page.screenshot({ type: "png" });
await browser.close();
await writeFile(path.join(assets, "social-card.png"), png);
console.log(`wrote social-card.png (${(png.length / 1024).toFixed(0)} KB)`);
